#include "director_native_wakes2.hpp"
#include "resident/domains/tasks/task_model.hpp"
#include "resident/domains/actor_foundation/military_availability.hpp"
namespace hanmo::resident {namespace {
bool same(const SubjectWake2&a,const SubjectWake2&b){return (a.subject.kind==b.subject.kind&&a.subject.id==b.subject.id)&&a.kind==b.kind&&a.source_schema==b.source_schema&&a.source_revision==b.source_revision&&a.actual_source.domain==b.actual_source.domain&&a.actual_source.kind==b.actual_source.kind&&a.actual_source.id==b.actual_source.id;}
Status emit_work(const DirectorWorkWakeRead2&x,const DirectorOriginalWakeVisitor2&emit,const StableId&actor,const SourceRef&ref,Integer schema,const WorldMoment&at){if(actor.empty()||!x.common.actor(actor))return common_failure("WorkWakeActorMissing",ref.id);auto past=compare_world_moments(at,x.actual);if(!past.ok)return {false,{},past.error};if(past.value>0)return common_failure("DirectorFutureWorkWake",ref.id);return emit({{SubjectKind::actor,actor},SubjectWakeKind2::commitment,ref,schema,0},at);}
}
Status visit_director_work_wakes2(const DirectorWorkWakeRead2&x,const DirectorOriginalWakeVisitor2&emit){
 if(!emit||!x.definitions.bound_to(x.common,x.tasks)||&x.supervision.common!=&x.common||&x.supervision.tasks!=&x.tasks||&x.supervision.original!=&x.original)return common_failure("DirectorWorkWakeBindingRequired");if(!x.tasks.work_execution)return common_success();const auto&s=*x.tasks.work_execution;
 auto source=[&](const char*kind,const StableId&id,Integer schema)->Outcome<WorldMoment>{const SourceRef r{"tasks",kind,id};if(r.kind=="work_task_offered"||r.kind=="work_task_accepted")return x.definitions.read_source_moment(r,schema);if(supervision_source_kind(r.kind))return read_supervision_source_moment(x.supervision,r,schema);return read_work_source_moment(x.common,x.tasks,x.original,r,schema);};
 auto actor=[&](const char*kind,const StableId&id,Integer schema,const StableId&who)->Status{auto at=source(kind,id,schema);if(!at.ok)return {false,{},at.error};return emit_work(x,emit,who,{"tasks",kind,id},schema,at.value);};
 for(const auto&row:s.work_task_offers.rows()){auto v=actor("work_task_offered",row.first,1,row.second.executor_actor_id);if(!v.ok)return v;if(row.second.presenting_actor_id!=row.second.executor_actor_id){v=actor("work_task_offered",row.first,1,row.second.presenting_actor_id);if(!v.ok)return v;}}
 for(const auto&row:s.work_task_acceptances.rows()){auto v=actor("work_task_accepted",row.first,1,row.second.executor_actor_id);if(!v.ok)return v;}
 for(const auto&row:s.acceptances.rows()){const auto*accepted=s.work_task_acceptances.find(row.second.original_task_acceptance.source_ref.id);if(!accepted)return common_failure("WorkWakeTaskAcceptanceMissing",row.first);auto v=actor("work_accepted",row.first,1,accepted->executor_actor_id);if(!v.ok)return v;}
 for(const auto&row:s.period_receipts.rows()){auto v=actor("work_period_receipt",row.first,2,row.second.leader_actor_id);if(!v.ok)return v;}
 for(const auto&row:s.leader_changes.rows()){auto v=actor("work_leader_changed",row.first,1,row.second.old_actor_id);if(!v.ok)return v;v=actor("work_leader_changed",row.first,1,row.second.new_actor_id);if(!v.ok)return v;}
 // Only the actual local final leader sees their own execution close. Remote
 // principals and previously replaced leaders wait for real report delivery.
 for(const auto&row:s.results.rows()){const auto&r=row.second;const auto*episode=s.episodes.find(r.work_id);if(!episode)return common_failure("WorkWakeEpisodeMissing",row.first);const StableId*who=nullptr;if(!episode->accepted_period_refs.empty()){const auto*p=s.period_receipts.find(episode->accepted_period_refs.back());if(!p)return common_failure("WorkWakePeriodMissing",row.first);who=&p->leader_actor_id;}else{const auto*a=s.acceptances.find(episode->acceptance_source_ref);const auto*t=a?s.work_task_acceptances.find(a->original_task_acceptance.source_ref.id):nullptr;if(!t)return common_failure("WorkWakeTaskAcceptanceMissing",row.first);who=&t->executor_actor_id;}auto v=actor(r.kind==WorkKind::patrol?"patrol_work_result":"supervised_work_result",row.first,1,*who);if(!v.ok)return v;}
 for(const auto&row:s.supervision_starts.rows()){auto v=actor("supervision_action_started",row.first,1,row.second.actor_id);if(!v.ok)return v;}
 for(const auto&row:s.supervision_window_closures.rows()){const auto*a=s.supervision_starts.find(row.second.start_source_ref);if(!a)return common_failure("WorkWakeActionStartMissing",row.first);auto v=actor("supervision_window_closed",row.first,1,a->actor_id);if(!v.ok)return v;}
 for(const auto&row:s.supervision_terminals.rows()){const auto*a=s.supervision_starts.find(row.second.start_source_ref);if(!a)return common_failure("WorkWakeActionStartMissing",row.first);auto v=actor("supervision_action_ended",row.first,1,a->actor_id);if(!v.ok)return v;}
 return common_success();
}
Status validate_director_work_wake2(const DirectorWorkWakeRead2&x,const SubjectWake2&wake){if(wake.kind!=SubjectWakeKind2::commitment||wake.actual_source.domain!="tasks")return common_failure("DirectorWorkWakeKindMismatch",wake.actual_source.id);bool found=false;auto valid=visit_director_work_wakes2(x,[&](const SubjectWake2&w,const WorldMoment&){if(same(w,wake))found=true;return common_success();});return !valid.ok?valid:found?common_success():common_failure("DirectorWorkWakeSourceMismatch",wake.actual_source.id);}
Status visit_director_capability_wakes2(const CharacterConditionSources&body,const DirectorOriginalWakeVisitor2&emit){
 if(!emit)return common_failure("DirectorCapabilityWakeVisitorRequired");for(const auto&row:body.state.character_condition_extensions.applied_receipts.rows()){const auto&r=row.second;bool changed=!r.created_effect_keys.empty()||!r.recovery_resolution_refs.empty()||r.capability_application.has_value();for(const auto&v:r.scalar_changes)changed=changed||v.before!=v.after;if(!changed)continue;auto source=read_character_condition_source(body,character_condition_receipt_source({row.first}),2);if(!source.ok)return {false,{},source.error};auto v=emit({{SubjectKind::actor,source.value.actor_id},SubjectWakeKind2::capability,source.value.source,2,source.value.condition_revision},source.value.occurred_at);if(!v.ok)return v;}
 for(const auto&row:body.state.character_condition_extensions.capacity_transitions.rows()){auto source=read_verified_military_availability_transition(body,row.first);if(!source.ok)return {false,{},source.error};const auto&r=*source.value;if(r.from==r.to)continue;auto v=emit({{SubjectKind::actor,r.actor_id},SubjectWakeKind2::capability,military_availability_transition_source(row.first),2,0},r.effective_at.exact_moment);if(!v.ok)return v;}
 return common_success();
}
Status validate_director_capability_wake2(const CharacterConditionSources&body,const SubjectWake2&wake){if(wake.kind!=SubjectWakeKind2::capability||wake.actual_source.domain!="actor_foundation")return common_failure("DirectorCapabilityWakeKindMismatch",wake.actual_source.id);bool found=false;auto valid=visit_director_capability_wakes2(body,[&](const SubjectWake2&w,const WorldMoment&){if(same(w,wake))found=true;return common_success();});return !valid.ok?valid:found?common_success():common_failure("DirectorCapabilityWakeSourceMismatch",wake.actual_source.id);}
}
